# Notebook 11. Speculative decoding and quantization: correctness before speed


**Module 11 — hands-on notebook**

First establish that proposal and correction recover the target law, including
boundary cases. Then examine cycle cost and quantization error. All experiments
run on CPU; timing estimates belong to the stated cost model:

- `p` and `q` are finite normalized distributions of the same shape;
- `q[t] = 0` causes no division by zero: the draft cannot propose that token and target
  mass returns through the residual;
- when `p == q`, rejection is impossible and the residual stays zero rather than `0/0`;
- `alpha = 1` in expected cycle length is handled without a singularity;
- the grouped quantizer handles an all-zero group explicitly;
- the bandwidth model distinguishes decimal `TB/s`/`GB` from binary `GiB`.

**Colab contract:** `Runtime → Run all` completes the mandatory path on CPU in a clean
session. The notebook reads no repository files and needs no upload, Google Drive, API
key, or paid service. The frozen M11 numerical contract is embedded and checked by
SHA-256.

def _positive_int(name: str, value: int) -> int:
    """Return a strictly positive, non-boolean integer."""
    if isinstance(value, bool) or not isinstance(value, (int, np.integer)) or int(value) <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return int(value)


def _non_negative_int(name: str, value: int) -> int:
    """Return a non-negative, non-boolean integer."""
    if isinstance(value, bool) or not isinstance(value, (int, np.integer)) or int(value) < 0:
        raise ValueError(f"{name} must be a non-negative integer")
    return int(value)


def _finite_non_negative(name: str, value: float) -> float:
    """Return a finite real value greater than or equal to zero."""
    if isinstance(value, bool) or not isinstance(value, (int, float, np.integer, np.floating)):
        raise ValueError(f"{name} must be a real number")
    number = float(value)
    if not math.isfinite(number) or number < 0.0:
        raise ValueError(f"{name} must be finite and non-negative")
    return number


def _positive_finite(name: str, value: float) -> float:
    """Return a strictly positive finite real value."""
    number = _finite_non_negative(name, value)
    if number == 0.0:
        raise ValueError(f"{name} must be positive")
    return number


def _probability(name: str, value: float) -> float:
    """Return a finite probability in [0, 1]."""
    number = _finite_non_negative(name, value)
    if number > 1.0:
        raise ValueError(f"{name} must lie in [0, 1]")
    return number


def probability_vector(name: str, values: Sequence[float], *, atol: float = 1e-12) -> np.ndarray:
    """Validate a 1D probability vector without silently renormalizing it."""
    array = np.asarray(values, dtype=np.float64)
    if array.ndim != 1 or array.size < 2:
        raise ValueError(f"{name} must be a 1D vector with at least two entries")
    if not np.isfinite(array).all() or np.any(array < 0.0):
        raise ValueError(f"{name} must contain finite non-negative probabilities")
    total = float(array.sum(dtype=np.float64))
    if not math.isclose(total, 1.0, rel_tol=0.0, abs_tol=atol):
        raise ValueError(f"{name} must sum to 1; got {total}")
    return array.copy()


def validate_probability_pair(p_values: Sequence[float], q_values: Sequence[float]) -> tuple[np.ndarray, np.ndarray]:
    """Validate target and draft vectors and require equal vocabulary shape."""
    p = probability_vector("p", p_values)
    q = probability_vector("q", q_values)
    if p.shape != q.shape:
        raise ValueError(f"p and q must share a shape; got {p.shape} and {q.shape}")
    return p, q


@dataclass(frozen=True)
class RejectionTrace:
    """Exact one-token rejection decomposition for fixed p and q."""
    p: np.ndarray
    q: np.ndarray
    acceptance_by_token: np.ndarray
    alpha: float
    residual: np.ndarray
    residual_mass: float
    total_variation: float
    balance: np.ndarray


def rejection_trace(p_values: Sequence[float], q_values: Sequence[float]) -> RejectionTrace:
    """Build an exact balance, including q[t]=0 and p==q edge cases."""
    p, q = validate_probability_pair(p_values, q_values)
    acceptance = np.zeros_like(p)
    support = q > 0.0
    acceptance[support] = np.minimum(1.0, p[support] / q[support])

    overlap = np.minimum(p, q)
    alpha = float(overlap.sum(dtype=np.float64))
    positive = np.maximum(p - q, 0.0)
    residual_mass = float(positive.sum(dtype=np.float64))
    residual = positive / residual_mass if residual_mass > 0.0 else np.zeros_like(positive)
    balance = overlap + residual_mass * residual
    tv = 0.5 * float(np.abs(p - q).sum(dtype=np.float64))

    assert math.isclose(residual_mass, 1.0 - alpha, abs_tol=1e-12)
    assert np.allclose(balance, p, atol=1e-12, rtol=0.0)
    assert math.isclose(alpha, 1.0 - tv, abs_tol=1e-12)
    return RejectionTrace(p, q, acceptance, alpha, residual, residual_mass, tv, balance)


